//! A-03 Skill Staleness — integration tests for S-05, S-07, P-06 outcomes.

use std::fs;
use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("failed to run residual binary")
}

fn init_with_low_token_warn(dir: &TempDir, token_warn: usize) {
    let out = run(dir, &["init"]);
    assert!(out.status.success(), "init failed: {}", String::from_utf8_lossy(&out.stderr));
    let config_path = dir.path().join("residual/config.toml");
    let raw = fs::read_to_string(&config_path).unwrap();
    let lowered = raw.replace("token_warn = 1000", &format!("token_warn = {token_warn}"));
    fs::write(&config_path, lowered).unwrap();
}

// --- S-05: token warnings in skill-list and skill-show ---

#[test]
fn skill_list_warns_when_tokens_exceed_token_warn() {
    let dir = TempDir::new().unwrap();
    init_with_low_token_warn(&dir, 10);
    let out = run(&dir, &["skill-list"]);
    assert!(out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        stderr.contains("warning:") && stderr.contains("token_warn"),
        "expected token_warn warning on stderr, got:\n{stderr}"
    );
}

#[test]
fn skill_show_warns_when_tokens_exceed_token_warn() {
    let dir = TempDir::new().unwrap();
    init_with_low_token_warn(&dir, 10);
    let out = run(&dir, &["skill-show", "purpose-walk"]);
    assert!(out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        stderr.contains("warning:") && stderr.contains("token_warn"),
        "expected token_warn warning on stderr, got:\n{stderr}"
    );
}

// --- S-07: passthrough stubs delegate content to binary ---

#[test]
fn skill_install_writes_passthrough_stub_without_version() {
    let dir = TempDir::new().unwrap();
    init_with_low_token_warn(&dir, 1000);
    let out = run(
        &dir,
        &["skill-install", "purpose-walk", "--agent", "agnostic"],
    );
    assert!(out.status.success(), "install failed: {}", String::from_utf8_lossy(&out.stderr));
    let stub_path = dir.path().join(".residual/skills/purpose-walk.md");
    assert!(stub_path.exists(), "stub should be installed");
    let content = fs::read_to_string(&stub_path).unwrap();
    assert!(
        content.contains("passthrough: true"),
        "stub should declare passthrough, got:\n{content}"
    );
    assert!(
        !content.contains("version:"),
        "passthrough stub must not track version, got:\n{content}"
    );
    assert!(
        content.contains("skill-show purpose-walk"),
        "stub should delegate to binary, got:\n{content}"
    );
    assert!(
        !content.contains("Socratically define the project's purposes"),
        "stub must not embed full skill body, got:\n{content}"
    );
}

#[test]
fn skill_check_green_for_passthrough_stub() {
    let dir = TempDir::new().unwrap();
    init_with_low_token_warn(&dir, 1000);
    run(&dir, &["skill-install", "purpose-walk", "--agent", "agnostic"]);
    let out = run(
        &dir,
        &["skill-check", "purpose-walk", "--agent", "agnostic"],
    );
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("up to date") && stdout.contains("passthrough"),
        "passthrough stub should stay green, got:\n{stdout}"
    );
}

// --- P-06 / S-01: embedded version parsed from skill front-matter ---

#[test]
fn skill_check_detects_outdated_legacy_versioned_install() {
    let dir = TempDir::new().unwrap();
    init_with_low_token_warn(&dir, 1000);
    let stub_dir = dir.path().join(".residual/skills");
    fs::create_dir_all(&stub_dir).unwrap();
    fs::write(
        stub_dir.join("purpose-walk.md"),
        "---\nname: purpose-walk\nversion: 0\n---\n# old full install\n",
    )
    .unwrap();
    let out = run(
        &dir,
        &["skill-check", "purpose-walk", "--agent", "agnostic"],
    );
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("outdated"),
        "legacy versioned install should report outdated when embedded is newer, got:\n{stdout}"
    );
}

