/// Static stub installed by `skill-install`; content always comes from the binary.
pub fn render_passthrough_stub(name: &str) -> String {
    let title: String = name
        .split('-')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                None => String::new(),
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ");
    format!(
        "---\nname: {name}\npassthrough: true\n---\n\n\
         # {title}\n\n\
         This skill delegates content to the `residual` binary. Always use the embedded definition:\n\n\
         ```bash\nresidual skill-show {name}\n```\n\n\
         At session start:\n\n\
         ```bash\nresidual skill-data {name}\n```\n"
    )
}

pub fn is_passthrough_stub(content: &str) -> bool {
    let mut lines = content.lines();
    if lines.next()?.trim() != "---" {
        return false;
    }
    for line in lines {
        if line.trim() == "---" {
            break;
        }
        if line.trim() == "passthrough: true" {
            return true;
        }
    }
    false
}

