use std::fs;
use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .unwrap()
}

fn init_low_warn(dir: &TempDir, token_warn: usize) {
    assert!(run(dir, &["init"]).status.success());
    let p = dir.path().join("residual/config.toml");
    let raw = fs::read_to_string(&p).unwrap();
    fs::write(p, raw.replace("token_warn = 1000", &format!("token_warn = {token_warn}"))).unwrap();
}

#[test]
fn skill_list_warns_when_tokens_exceed_token_warn() {
    let dir = TempDir::new().unwrap();
    init_low_warn(&dir, 10);
    let out = run(&dir, &["skill-list"]);
    assert!(out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("warning:") && stderr.contains("token_warn"), "{stderr}");
}

#[test]
fn skill_show_warns_when_tokens_exceed_token_warn() {
    let dir = TempDir::new().unwrap();
    init_low_warn(&dir, 10);
    let out = run(&dir, &["skill-show", "purpose-walk"]);
    assert!(out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("warning:") && stderr.contains("token_warn"), "{stderr}");
}

#[test]
fn skill_install_writes_passthrough_stub_without_version() {
    let dir = TempDir::new().unwrap();
    init_low_warn(&dir, 1000);
    assert!(run(&dir, &["skill-install", "purpose-walk", "--agent", "agnostic"]).status.success());
    let content = fs::read_to_string(dir.path().join(".residual/skills/purpose-walk.md")).unwrap();
    assert!(content.contains("passthrough: true"));
    assert!(!content.contains("version:"));
    assert!(content.contains("skill-show purpose-walk"));
    assert!(!content.contains("Socratically define"));
}

#[test]
fn skill_check_green_for_passthrough_stub() {
    let dir = TempDir::new().unwrap();
    init_low_warn(&dir, 1000);
    run(&dir, &["skill-install", "purpose-walk", "--agent", "agnostic"]);
    let out = run(&dir, &["skill-check", "purpose-walk", "--agent", "agnostic"]);
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.contains("up to date") && stdout.contains("passthrough"), "{stdout}");
}

#[test]
fn skill_check_detects_outdated_legacy_versioned_install() {
    let dir = TempDir::new().unwrap();
    init_low_warn(&dir, 1000);
    let p = dir.path().join(".residual/skills");
    fs::create_dir_all(&p).unwrap();
    fs::write(p.join("purpose-walk.md"), "---\nname: purpose-walk\nversion: 0\n---\n# old\n").unwrap();
    let out = run(&dir, &["skill-check", "purpose-walk", "--agent", "agnostic"]);
    assert!(String::from_utf8_lossy(&out.stdout).contains("outdated"));
}

