use anyhow::{Context, Result};
use crate::config::Config;
pub mod context; pub mod install; pub mod installer; pub mod personas; pub mod phases; pub mod research;
pub const SKILLS: &[(&str, &str, u32)] = &[
    ("purpose-walk", include_str!("definitions/purpose_walk.md"), 0),
    ("naive-draft", include_str!("definitions/naive_draft.md"), 0),
    ("stressor-walk", include_str!("definitions/stressor_walk.md"), 0),
    ("integrate", include_str!("definitions/integrate.md"), 0),
    ("fmea", include_str!("definitions/fmea.md"), 0),
    ("atam", include_str!("definitions/atam.md"), 0),
];
pub fn find(name: &str) -> Option<(&'static str, u32)> {
    SKILLS.iter().find(|(n,_,_)|*n==name).map(|(_,c,_)|(*c,install::parse_version_from_front_matter(c).unwrap_or(0)))
}
pub fn show(cfg:&Config,name:&str,version_only:bool)->Result<()>{
    let(content,version)=find(name).with_context(||format!("skill '{}' not found",name))?;
    if !version_only { maybe_warn_tokens(name,content,cfg.skills.token_warn); }
    if version_only { println!("{}",version); } else { print!("{}",content); }
    Ok(())
}
pub fn install(name:&str,agent:&str,global:bool)->Result<()>{
    if find(name).is_none(){anyhow::bail!("skill '{}' not found",name);}
    let agent_parsed:install::Agent=agent.parse()?; let path=install::install_path(name,&agent_parsed,global)?;
    install::write_skill(&path,&install::render_passthrough_stub(name))?;
    println!("Installed '{}' to {}",name,path.display()); Ok(())
}
pub fn data(cfg:&Config,name:&str)->Result<()>{
    if find(name).is_none(){anyhow::bail!("skill '{}' not found",name);} print!("{}",context::build(cfg,name)?); Ok(())
}
pub fn list_all(cfg:&Config)->Result<()>{
    println!("{:<20} {:>7}  {:>12}","SKILL","VERSION","TOKENS (~)"); println!("{}", "-".repeat(44));
    for(name,content,_) in SKILLS { let(_,version)=find(name).unwrap(); maybe_warn_tokens(name,content,cfg.skills.token_warn);
        println!("{:<20} {:>7}  {:>12}",name,version,estimate_tokens(content)); } Ok(())
}
pub fn check(name:&str,agent:&str)->Result<()>{
    let(_,embedded_version)=find(name).with_context(||format!("skill '{}' not found",name))?;
    let agent_parsed:install::Agent=agent.parse()?; let path=install::install_path(name,&agent_parsed,false)?;
    if !path.exists(){ println!("'{}' is not installed for agent '{}'.",name,agent); return Ok(()); }
    let installed_content=std::fs::read_to_string(&path).with_context(||format!("failed to read {}",path.display()))?;
    if install::is_passthrough_stub(&installed_content){ println!("'{}' is up to date (passthrough stub delegates to binary).",name); return Ok(()); }
    match install::parse_version_from_front_matter(&installed_content){
        None=>println!("'{}' is outdated: installed file has no version; embedded version {}.",name,embedded_version),
        Some(v) if v==embedded_version=>println!("'{}' is up to date (version {}).",name,v),
        Some(v)=>println!("'{}' is outdated: installed version {}, embedded version {}.",name,v,embedded_version),
    } Ok(())
}
pub fn generate_completions()->Result<()>{crate::cli::help::generate_completions()}
pub fn generate_man()->Result<()>{crate::cli::help::generate_man()}
pub fn install_hook()->Result<()>{crate::verification::git_hook::install()}
pub fn estimate_tokens(content:&str)->usize{(content.len() as f64*0.75) as usize}
fn maybe_warn_tokens(name:&str,content:&str,token_warn:usize){
    let tokens=estimate_tokens(content);
    if tokens>token_warn { eprintln!("warning: skill '{}' estimated tokens ({}) exceed token_warn limit ({})",name,tokens,token_warn); }
}
#[cfg(test)] mod tests { use super::*; #[test] fn find_reads_version_from_front_matter(){ assert_eq!(find("purpose-walk").unwrap().1,1);} }
